check 'credential never entered a tracked file' '"$PY" .claude/skills/verify-gate/scripts/guards.py secret --base d854632b919eb291cf7f7f685087147cbe4db9ac'
check 'delivered: monitor/runs/2026-07-31T170455Z-P1REPLAYLIVE/MANIFEST.json' 'test -e '\''monitor/runs/2026-07-31T170455Z-P1REPLAYLIVE/MANIFEST.json'\'''
check 'spotcheck driver overall' 'cd monitor/runs/2026-07-31T170455Z-P1REPLAYLIVE && python -c "import json;s=json.load(open('\''summary.json'\'',encoding='\''utf-8'\''));assert s['\''integrity'\'']['\''hash_mismatches'\'']==0 and s['\''adapter_honesty_violations'\'']==0 and all(s[k]['\''verdict'\'']=='\''PASS'\'' for k in ('\''live_g50t'\'','\''combined_g50t'\'','\''combined_ar25'\'','\''sk48_supplement'\'')), s;print('\''spotcheck summary green'\'')"'

